// Hand-written. Not generated by Speakeasy.
//
// A plan that changes one attribute reports most of the others as "known
// after apply".
//
// The framework marks every computed attribute the configuration leaves unset
// as unknown as soon as the proposed new state differs from prior state
// anywhere:
//
//	server_planresourcechange.go:252  computed nulls become unknown
//
// It is one decision for the whole resource, not one per attribute, so the
// size of the edit makes no difference. A service carries over 200 attributes
// that are optional and computed, which is why editing `description` alone
// reports about 178 others as unknown and draws the lists among them as
// though their contents were being removed.
//
// settled_plan.go handles the case where the plan differs from prior state by
// nothing but these unknowns, which is what settles a reordered list and a
// fresh import. It stands down as soon as one genuine change appears, and
// that is the case this file covers.
//
// Which unknowns can be answered in advance
// -----------------------------------------
// An unknown is honest when the provider cannot predict what Authlete will
// store. That depends on whether the value is sent at all:
//
//   - Optional and computed. The user may set it, so Authlete accepts it as
//     input. Updating a service replaces the whole object, so the provider
//     sends back exactly what is in state and Authlete stores it unchanged.
//     Prior state is therefore the correct planned value, not a guess.
//
//   - Computed only. Authlete owns it and the provider never sends it.
//     `modified_at` is the clearest case: it moves on every update whatever
//     else happens. These have to stay unknown, because planning a value the
//     server then contradicts fails the apply with "Provider produced
//     inconsistent result after apply", which is worse than a verbose plan.
//
// Reading optionality off the schema rather than keeping a list by hand
// matters for a generated provider: attributes arrive with each regeneration,
// and a list would be wrong the moment one did. The five computed-only
// attributes that are genuinely immutable (`api_key`, `created_at`, `number`
// and so on) are already pinned through the overlay, so they do not rely on
// this.
//
// An unknown that came from the configuration is left alone. `jwks` built
// from a tls_private_key created in the same run is a value the user asked
// for and the provider cannot see yet, and absorbing it would silently skip
// the key rotation the migration guide recommends.
package provider

import (
	"context"

	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

// absorbSettledUnknowns replaces each unknown the framework invented with the
// value already in state, where the schema says Authlete will accept that
// value back unchanged.
//
// It is a no-op on create, on destroy, and on a plan that replaces the
// resource, none of which have a prior state worth keeping.
func absorbSettledUnknowns(ctx context.Context, req resource.ModifyPlanRequest, resp *resource.ModifyPlanResponse) {
	if req.State.Raw.IsNull() || req.Plan.Raw.IsNull() || resp.Plan.Raw.IsNull() {
		return
	}
	if len(resp.RequiresReplace) > 0 {
		return
	}

	planned, err := tftypes.Transform(resp.Plan.Raw, func(path *tftypes.AttributePath, val tftypes.Value) (tftypes.Value, error) {
		if val.IsKnown() {
			return val, nil
		}
		// Some attributes Authlete recomputes when the object is written,
		// from settings that live on another object. Prior state is then a
		// prediction rather than a value, and a wrong one as soon as the
		// other object has moved on.
		if recomputedOnWrite(path) {
			return val, nil
		}
		// Inside a collection, a path identifies an element by position, and
		// position is not identity. Add a scope at the front of
		// supported_scopes and element 0 of the plan is a different scope
		// from element 0 of prior state, so the description stored for one
		// would be planned for the other.
		if throughCollection(path) {
			return val, nil
		}
		// Only an attribute the user may set is one the provider sends back,
		// and only a value the provider sends back is one Authlete is bound to
		// return unchanged.
		attr, err := req.Plan.Schema.AttributeAtTerraformPath(ctx, path)
		if err != nil || !attr.IsOptional() {
			return val, nil
		}
		// Unknown because the framework invented it, not because the
		// configuration holds a value that is not resolved yet.
		if cfg, ok := valueAt(req.Config.Raw, path); !ok || !cfg.IsNull() {
			return val, nil
		}
		prior, ok := valueAt(req.State.Raw, path)
		if !ok || !prior.IsKnown() {
			return val, nil
		}
		return prior, nil
	})
	if err != nil {
		// Leaving the plan verbose is always safe. Reporting an error here
		// would turn a cosmetic problem into a broken plan.
		return
	}
	resp.Plan.Raw = planned
}

// valueAt returns the value at path, and whether the path resolves to one.
// A path that does not exist in the given value is not an error here: state
// written by an earlier schema version may simply not have the attribute.
func valueAt(in tftypes.Value, path *tftypes.AttributePath) (tftypes.Value, bool) {
	raw, remaining, err := tftypes.WalkAttributePath(in, path)
	if err != nil || len(remaining.Steps()) > 0 {
		return tftypes.Value{}, false
	}
	val, ok := raw.(tftypes.Value)
	return val, ok
}

// throughCollection reports whether the path reaches its value through a list,
// set or map element.
//
// The attributes of a single nested object are addressed by name and keep
// their identity, so they are not affected.
func throughCollection(path *tftypes.AttributePath) bool {
	for _, step := range path.Steps() {
		switch step.(type) {
		case tftypes.ElementKeyInt, tftypes.ElementKeyString, tftypes.ElementKeyValue:
			return true
		}
	}
	return false
}

// serverRecomputedRoots are the attributes Authlete rebuilds from the service
// when a client is written, rather than storing what it was sent.
//
// Both are filtered against settings held on the service: a requestable scope
// the service no longer defines is dropped, and a custom metadata key the
// service no longer declares is dropped with it. The client keeps the old
// value until something writes to it, so prior state is accurate right up to
// the moment it stops being accurate, which is the apply itself.
//
// Answering these from prior state writes the prediction into state and loses
// what Authlete returned, so they stay unknown and are read back from the
// response like any value only the server knows.
//
// This list is empirical, not derived from the schema, and so is only as
// complete as the cases that have been measured. testing/run.sh drift
// compares state against the API after an apply and fails on any attribute
// that disagrees, which is how a missing entry is meant to be found.
var serverRecomputedRoots = map[string]bool{
	"extension":       true, // holds requestable_scopes
	"custom_metadata": true,
}

// recomputedOnWrite reports whether the attribute at the root of path is one
// Authlete rebuilds on write.
func recomputedOnWrite(path *tftypes.AttributePath) bool {
	steps := path.Steps()
	if len(steps) == 0 {
		return false
	}
	name, ok := steps[0].(tftypes.AttributeName)
	return ok && serverRecomputedRoots[string(name)]
}
